-- glossary
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('BMI', $md$Body Mass Index — angka yang dihitung dari berat dan tinggi badan untuk menggambarkan kategori berat secara umum (kurus, normal, overweight, obesitas). Praktis tapi terbatas: BMI tidak bisa membedakan otot dan lemak, jadi bukan diagnosis kesehatan.$md$, (select id from public.knowledge_articles where slug = 'bmi-itu-apa' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('BMR', $md$Basal Metabolic Rate — jumlah kalori yang dibakar tubuhmu saat istirahat total, hanya untuk menjaga fungsi dasar seperti bernapas dan detak jantung. Biasanya dihitung dengan rumus Mifflin-St Jeor dari umur, jenis kelamin, tinggi, dan berat.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('TDEE', $md$Total Daily Energy Expenditure — total kalori yang kamu bakar dalam sehari, yaitu BMR ditambah aktivitas fisik dan pencernaan makanan. Angka inilah yang jadi patokan kebutuhan kalori harianmu.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Kalori', $md$Satuan energi dari makanan dan minuman. Tubuh memakainya untuk semua aktivitas, dari bernapas sampai olahraga. Kalori itu netral — bukan musuh, tapi juga perlu dikelola.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Defisit kalori', $md$Kondisi saat kalori yang masuk lebih sedikit dari yang dibakar tubuh (TDEE). Ini prinsip dasar penurunan berat yang sehat — idealnya defisit ringan sekitar 300–500 kkal per hari, bukan ekstrem.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Surplus kalori', $md$Kondisi saat kalori yang masuk lebih banyak dari yang dibakar tubuh. Dibutuhkan kalau targetmu menaikkan berat badan atau membangun massa otot — tetap sebaiknya bertahap dan dari makanan bergizi.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Protein', $md$Zat gizi pembangun otot dan jaringan tubuh, juga bikin kenyang lebih lama dibanding karbohidrat atau lemak. Sumbernya: telur, ayam, ikan, tahu, tempe, dan kacang-kacangan.$md$, (select id from public.knowledge_articles where slug = 'protein-fondasi' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Karbohidrat', $md$Sumber energi utama tubuh, dipecah menjadi glukosa sebagai bahan bakar otak dan otot. Tidak perlu dihindari total — pilih yang berserat seperti nasi merah, oat, dan umbi-umbian.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Lemak', $md$Zat gizi sumber energi cadangan yang juga penting untuk hormon dan penyerapan vitamin. Yang perlu dibatasi adalah lemak trans dan lemak jenuh berlebih, bukan semua lemak.$md$, null, 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Serat', $md$Bagian tumbuhan yang tidak dicerna tubuh, tapi bikin kenyang lebih lama dan membantu pencernaan. Ada di sayur, buah, dan biji-bijian utuh.$md$, (select id from public.knowledge_articles where slug = 'serat-kenyang-lebih-lama' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Metabolisme', $md$Semua proses kimia di tubuh yang mengubah makanan menjadi energi. Kecepatannya dipengaruhi massa otot, umur, dan aktivitas — bukan sesuatu yang 'rusak' permanen karena sekali diet.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Massa otot', $md$Total otot di tubuhmu. Otot membakar lebih banyak kalori dibanding lemak bahkan saat istirahat, jadi menjaga massa otot penting saat menurunkan berat badan.$md$, (select id from public.knowledge_articles where slug = 'otot-vs-lemak' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Lemak visceral', $md$Lemak yang menumpuk di sekitar organ dalam perut. Jenis ini lebih berkaitan dengan risiko kesehatan dibanding lemak di bawah kulit, dan lingkar pinggang adalah cara sederhana memantaunya.$md$, (select id from public.knowledge_articles where slug = 'lingkar-pinggang' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Lingkar pinggang', $md$Ukuran keliling perut setinggi pusar. Pelengkap BMI yang murah dan gampang: umumnya dianjurkan di bawah 90 cm untuk pria dan 80 cm untuk wanita Asia.$md$, (select id from public.knowledge_articles where slug = 'lingkar-pinggang' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Plateau', $md$Fase saat berat badan berhenti turun padahal pola makan dan aktivitas tidak berubah. Ini normal — tubuh beradaptasi — dan biasanya terlewati dengan evaluasi porsi, aktivitas, atau sekadar bersabar.$md$, null, 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Yo-yo dieting', $md$Pola turun-naik berat badan berulang akibat diet ekstrem yang tidak bertahan lama. Selain melelahkan mental, pola ini bikin makin sulit menjaga berat stabil jangka panjang.$md$, (select id from public.knowledge_articles where slug = 'diet-ekstrem-vs-pola-makan' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Indeks glikemik', $md$Skala seberapa cepat suatu makanan menaikkan gula darah. Makanan indeks glikemik rendah (mis. oat, kacang) menaikkan gula darah lebih perlahan dan bikin kenyang lebih lama.$md$, null, 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Gula darah', $md$Kadar glukosa di dalam darah, sumber energi utama sel tubuh. Naik-turunnya dipengaruhi makanan, aktivitas, tidur, dan stres — bukan cuma soal makan manis.$md$, null, 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Porsi', $md$Jumlah makanan yang kamu ambil dalam sekali makan. Mengatur porsi — misalnya dengan piring lebih kecil atau berhenti sebelum terlalu kenyang — adalah cara paling sederhana mengendalikan asupan tanpa diet ketat.$md$, (select id from public.knowledge_articles where slug = 'mindful-eating' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('NEAT', $md$Non-Exercise Activity Thermogenesis — kalori yang terbakar dari aktivitas sehari-hari di luar olahraga: jalan kaki, naik tangga, beres-beres rumah. Sering diremehkan, padahal kontribusinya besar.$md$, (select id from public.knowledge_articles where slug = 'jalan-kaki-underrated' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Latihan kekuatan', $md$Olahraga melawan beban — angkat beban, push-up, squat — yang membangun dan menjaga massa otot. Penting terutama saat defisit kalori agar yang susut lemak, bukan otot.$md$, (select id from public.knowledge_articles where slug = 'konsistensi-vs-intensitas' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Kardio', $md$Olahraga yang memacu jantung dan napas: lari, bersepeda, berenang, jalan cepat. Bagus untuk stamina dan membakar kalori, paling efektif kalau dilakukan rutin, bukan sesekali tapi brutal.$md$, (select id from public.knowledge_articles where slug = 'konsistensi-vs-intensitas' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Hidrasi', $md$Kecukupan cairan tubuh. Kadang rasa haus disalahartikan sebagai lapar, jadi minum cukup sebelum makan bisa membantu mengendalikan porsi secara alami.$md$, null, 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Mindful eating', $md$Makan dengan penuh perhatian: mengunyah pelan, merasakan rasa, dan berhenti saat cukup kenyang. Lawan dari makan sambil scroll HP sampai piring kosong tanpa sadar.$md$, (select id from public.knowledge_articles where slug = 'mindful-eating' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Sleep hygiene', $md$Kebiasaan tidur yang sehat: jadwal tidur teratur, kurangi layar sebelum tidur, dan kamar yang gelap dan sejuk. Kurang tidur mengacaukan hormon lapar-kenyang dan bikin gampang ngemil.$md$, (select id from public.knowledge_articles where slug = 'tidur-dan-berat-badan' and locale = 'id'), 'id') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('BMI', $md$Body Mass Index — a number calculated from your weight and height to describe weight category in general terms (underweight, normal, overweight, obese). Practical but limited: BMI can't tell muscle from fat, so it's not a health diagnosis.$md$, (select id from public.knowledge_articles where slug = 'bmi-itu-apa' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('BMR', $md$Basal Metabolic Rate — the calories your body burns at complete rest, just to keep basic functions like breathing and heartbeat going. Usually estimated with the Mifflin-St Jeor formula from age, sex, height, and weight.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('TDEE', $md$Total Daily Energy Expenditure — the total calories you burn in a day: your BMR plus physical activity and food digestion. This is the number that sets your daily calorie needs.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Calorie', $md$The unit of energy from food and drinks. Your body uses it for everything, from breathing to exercise. Calories are neutral — not the enemy, but worth managing.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Calorie deficit', $md$When the calories you take in are fewer than what your body burns (TDEE). This is the basic principle of healthy weight loss — ideally a gentle deficit of around 300–500 kcal per day, not an extreme one.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Calorie surplus', $md$When the calories you take in exceed what your body burns. It's needed if your goal is gaining weight or building muscle — still best done gradually and from nutritious food.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Protein', $md$The nutrient that builds muscle and body tissue, and keeps you full longer than carbs or fat. Sources: eggs, chicken, fish, tofu, tempeh, and legumes.$md$, (select id from public.knowledge_articles where slug = 'protein-fondasi' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Carbohydrates', $md$The body's main energy source, broken down into glucose to fuel the brain and muscles. No need to avoid them entirely — pick fibrous ones like brown rice, oats, and root vegetables.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Fat', $md$A nutrient that stores reserve energy and is also important for hormones and vitamin absorption. What needs limiting is trans fat and excess saturated fat — not all fat.$md$, null, 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Fiber', $md$The part of plants your body doesn't digest, but which keeps you full longer and helps digestion. Found in vegetables, fruit, and whole grains.$md$, (select id from public.knowledge_articles where slug = 'serat-kenyang-lebih-lama' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Metabolism', $md$All the chemical processes in your body that turn food into energy. Its speed is influenced by muscle mass, age, and activity — not something permanently 'broken' by a single diet.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Muscle mass', $md$The total muscle in your body. Muscle burns more calories than fat even at rest, so preserving muscle mass matters when losing weight.$md$, (select id from public.knowledge_articles where slug = 'otot-vs-lemak' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Visceral fat', $md$Fat stored around the internal organs in the belly. This type is more linked to health risks than fat under the skin, and waist circumference is a simple way to monitor it.$md$, (select id from public.knowledge_articles where slug = 'lingkar-pinggang' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Waist circumference', $md$The measurement around your belly at navel level. A cheap, easy complement to BMI: generally recommended below 90 cm for men and 80 cm for women in Asia.$md$, (select id from public.knowledge_articles where slug = 'lingkar-pinggang' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Weight-loss plateau', $md$A phase when your weight stops dropping even though your diet and activity haven't changed. It's normal — your body adapts — and it's usually passed by reviewing portions, activity, or simply being patient.$md$, null, 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Yo-yo dieting', $md$The pattern of repeatedly losing and regaining weight due to extreme diets that don't last. Besides being mentally exhausting, this pattern makes it harder to keep weight stable long-term.$md$, (select id from public.knowledge_articles where slug = 'diet-ekstrem-vs-pola-makan' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Glycemic index', $md$A scale of how quickly a food raises blood sugar. Low-glycemic foods (e.g., oats, nuts) raise blood sugar more slowly and keep you full longer.$md$, null, 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Blood sugar', $md$The level of glucose in the blood, the cells' main energy source. Its ups and downs are influenced by food, activity, sleep, and stress — not just sweet foods.$md$, null, 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Portion size', $md$The amount of food you take in one meal. Managing portions — for example with a smaller plate or stopping before you're overly full — is the simplest way to control intake without strict dieting.$md$, (select id from public.knowledge_articles where slug = 'mindful-eating' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('NEAT', $md$Non-Exercise Activity Thermogenesis — calories burned from everyday activity outside of exercise: walking, climbing stairs, tidying the house. Often underestimated, yet its contribution is significant.$md$, (select id from public.knowledge_articles where slug = 'jalan-kaki-underrated' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Strength training', $md$Exercise against resistance — lifting weights, push-ups, squats — that builds and maintains muscle mass. Especially important during a calorie deficit so that what shrinks is fat, not muscle.$md$, (select id from public.knowledge_articles where slug = 'konsistensi-vs-intensitas' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Cardio', $md$Exercise that gets the heart and lungs pumping: running, cycling, swimming, brisk walking. Great for stamina and burning calories, most effective when done regularly rather than occasionally but brutally.$md$, (select id from public.knowledge_articles where slug = 'konsistensi-vs-intensitas' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Hydration', $md$The body's fluid sufficiency. Thirst is sometimes mistaken for hunger, so drinking enough before meals can help control portions naturally.$md$, null, 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Mindful eating', $md$Eating with full attention: chewing slowly, tasting the food, and stopping when comfortably full. The opposite of eating while scrolling your phone until the plate is empty without noticing.$md$, (select id from public.knowledge_articles where slug = 'mindful-eating' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id, locale) values ('Sleep hygiene', $md$Healthy sleep habits: a regular sleep schedule, less screen time before bed, and a dark, cool bedroom. Lack of sleep disrupts hunger-fullness hormones and makes snacking tempting.$md$, (select id from public.knowledge_articles where slug = 'tidur-dan-berat-badan' and locale = 'en'), 'en') on conflict (term, locale) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();

-- quizzes
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at, locale) values ('kuis-bmi-dasar', 'Seberapa paham kamu soal BMI?', '5 soal cepat tentang arti dan batas BMI.', (select id from public.knowledge_articles where slug = 'bmi-itu-apa' and locale = 'id'), 'published', now(), 'id') on conflict (slug, locale) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id'), 0, 'BMI dihitung berdasarkan apa?', '["Berat badan dan tinggi badan", "Berat badan dan umur", "Lingkar pinggang dan tinggi badan", "Berat badan dan kadar lemak darah"]'::jsonb, 0, 'Rumus BMI sederhana: berat (kg) dibagi tinggi (m) kuadrat. Makanya praktis, tapi juga makanya ia tidak tahu komposisi tubuhmu.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id'), 1, 'BMI 22,5 masuk kategori apa untuk orang dewasa?', '["Underweight", "Normal", "Overweight", "Obesitas"]'::jsonb, 1, 'Rentang normal BMI dewasa adalah 18,5–24,9. Angka 22,5 duduk manis di tengahnya.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id'), 2, 'Apa keterbatasan utama BMI?', '["Rumusnya terlalu rumit untuk dipakai sehari-hari", "Tidak bisa membedakan massa otot dan lemak", "Hanya berlaku untuk orang yang sudah diet", "Berubah-ubah tergantung jam makan"]'::jsonb, 1, 'Atlet berotot bisa tercatat ''overweight'' padahal kadar lemaknya rendah. BMI itu skrining awal, bukan vonis.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id'), 3, 'Untuk anak dan remaja, penilaian BMI sebaiknya bagaimana?', '["Pakai kategori dewasa yang sama persis", "Tidak perlu diukur sampai umur 20 tahun", "Memakai kurva pertumbuhan/persentil sesuai umur dan jenis kelamin", "Cukup ditebak dari penampilan fisik"]'::jsonb, 2, 'Anak masih bertumbuh, jadi BMI-nya dibaca lewat persentil di kurva pertumbuhan — kategori dewasa tidak berlaku mentah-mentah.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'id'), 4, 'Seseorang dengan BMI 27 sebaiknya menyimpulkan apa?', '["Pasti tidak sehat dan harus diet ketat segera", "Masuk kategori overweight — jadikan pemicu untuk cek pola hidup secara menyeluruh", "BMI di atas 25 selalu berarti obesitas", "Tidak perlu peduli karena BMI tidak akurat sama sekali"]'::jsonb, 1, 'BMI 27 = overweight, tapi itu titik awal evaluasi (pola makan, aktivitas, lingkar pinggang), bukan diagnosis penyakit.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at, locale) values ('kuis-kalori-energi', 'Kalori & Energi', 'Tebak-tebakan soal kalori, BMR, dan TDEE.', (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'id'), 'published', now(), 'id') on conflict (slug, locale) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id'), 0, 'Sebenarnya kalori itu apa?', '["Zat berbahaya dalam makanan cepat saji", "Satuan energi yang dipakai tubuh untuk beraktivitas", "Jenis lemak yang menumpuk di perut", "Hormon yang bikin cepat lapar"]'::jsonb, 1, 'Kalori hanyalah satuan energi — tubuhmu butuh itu untuk bernapas, berpikir, sampai olahraga. Masalahnya cuma soal jumlah.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id'), 1, 'BMR menggambarkan apa?', '["Kalori yang terbakar saat olahraga intens", "Kalori maksimal yang boleh dimakan sehari", "Kalori yang dibakar tubuh saat istirahat total", "Kecepatan metabolisme setelah makan besar"]'::jsonb, 2, 'BMR adalah energi untuk fungsi dasar tubuh saat kamu rebahan seharian tanpa ngapa-ngapain — biasanya dihitung dengan rumus Mifflin-St Jeor.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id'), 2, 'Hubungan TDEE dan BMR yang benar adalah…', '["TDEE selalu lebih kecil dari BMR", "TDEE = BMR + energi aktivitas harian", "TDEE dan BMR adalah dua nama untuk hal yang sama", "TDEE hanya berlaku untuk atlet"]'::jsonb, 1, 'TDEE adalah total harian: BMR ditambah semua aktivitasmu. Inilah angka yang jadi patokan kebutuhan kalorimu.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id'), 3, 'Defisit kalori artinya…', '["Tidak makan sama sekali seharian", "Kalori masuk lebih sedikit dari yang dibakar tubuh", "Menghindari semua makanan berkalori tinggi selamanya", "Olahraga sampai kalori terbakar habis"]'::jsonb, 1, 'Defisit ringan sekitar 300–500 kkal per hari sudah cukup untuk turun berat secara sehat — tidak perlu sampai menyiksa diri.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'id'), 4, 'Perkiraan energi yang tersimpan dalam 1 kg lemak tubuh adalah sekitar…', '["3.500 kkal", "5.000 kkal", "7.700 kkal", "10.000 kkal"]'::jsonb, 2, 'Sekitar 7.700 kkal per kg lemak — makanya target realistis adalah turun bertahap sekitar 0,5 kg per minggu, bukan instan.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at, locale) values ('kuis-mitos-fakta', 'Mitos vs Fakta Kebiasaan Sehat', 'Bedakan mitos populer dari faktanya.', null, 'published', now(), 'id') on conflict (slug, locale) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id'), 0, 'Mitos atau fakta: ''Makan malam pasti bikin gemuk.''', '["Fakta — makan di atas jam 7 malam otomatis jadi lemak", "Mitos — yang menentukan adalah total kalori seharian, bukan jam makan", "Fakta — metabolisme berhenti total saat tidur", "Mitos — makan malam justru membakar kalori"]'::jsonb, 1, 'Tubuh tidak punya jam ajaib yang mengubah makanan jadi lemak tepat jam 7. Total asupan seharianlah yang menentukan.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id'), 1, 'Mitos atau fakta: ''Makin banyak keringat saat olahraga, makin banyak lemak terbakar.''', '["Fakta — keringat adalah lemak yang mencair", "Mitos — keringat terutama air; lemak keluar lewat napas dan metabolisme", "Fakta — berlaku untuk semua jenis olahraga", "Mitos — keringat tidak ada hubungannya sama sekali dengan olahraga"]'::jsonb, 1, 'Keringat adalah cara tubuh mendinginkan diri, isinya mostly air. Lemak yang terbakar justru sebagian besar keluar sebagai karbon dioksida lewat napas.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id'), 2, 'Mitos atau fakta: ''Karbohidrat harus dihindari total biar berat turun.''', '["Fakta — karbohidrat adalah satu-satunya penyebab kegemukan", "Mitos — karbohidrat adalah sumber energi utama; yang penting jenis dan porsinya", "Fakta — tubuh tidak membutuhkan karbohidrat sama sekali", "Mitos — karbohidrat tidak mengandung kalori"]'::jsonb, 1, 'Otak dan otot butuh glukosa dari karbohidrat. Pilih yang berserat dan atur porsinya — tidak perlu memusuhi satu zat gizi.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id'), 3, 'Mitos atau fakta: ''Menimbang badan tiap hari itu wajib biar berhasil.''', '["Fakta — tanpa timbangan harian diet pasti gagal", "Mitos — yang penting jadwal konsisten dan membaca tren, bukan angka harian", "Fakta — berat harian tidak pernah fluktuatif", "Mitos — menimbang justru dilarang total"]'::jsonb, 1, 'Berat harian naik-turun karena air dan makanan. Timbang dengan jadwal yang sama tiap minggu dan lihat trennya — itu data yang jujur.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'id'), 4, 'Mitos atau fakta: ''Kurang tidur bisa mengganggu pengelolaan berat badan.''', '["Mitos — tidur tidak ada hubungannya dengan berat badan", "Fakta — kurang tidur mengacaukan hormon lapar-kenyang dan bikin gampang ngemil", "Mitos — begadang justru membakar lebih banyak kalori", "Fakta — kurang tidur langsung menambah 5 kg"]'::jsonb, 1, 'Kurang tidur menaikkan hormon lapar (ghrelin) dan menurunkan hormon kenyang (leptin). Tidur cukup adalah bagian strategi yang sah.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at, locale) values ('kuis-bmi-dasar', 'How Well Do You Understand BMI?', '5 quick questions about the meaning and limits of BMI.', (select id from public.knowledge_articles where slug = 'bmi-itu-apa' and locale = 'en'), 'published', now(), 'en') on conflict (slug, locale) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en'), 0, 'What is BMI calculated from?', '["Weight and height", "Weight and age", "Waist circumference and height", "Weight and blood fat levels"]'::jsonb, 0, 'The BMI formula is simple: weight (kg) divided by height (m) squared. That''s why it''s practical — but also why it knows nothing about your body composition.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en'), 1, 'Which category does a BMI of 22.5 fall into for an adult?', '["Underweight", "Normal", "Overweight", "Obesity"]'::jsonb, 1, 'The normal adult BMI range is 18.5–24.9. A value of 22.5 sits comfortably in the middle.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en'), 2, 'What is the main limitation of BMI?', '["The formula is too complicated for daily use", "It can''t distinguish muscle mass from fat", "It only applies to people who are already dieting", "It changes depending on meal times"]'::jsonb, 1, 'A muscular athlete can be recorded as ''overweight'' despite low body fat. BMI is an initial screening tool, not a verdict.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en'), 3, 'For children and teenagers, how should BMI ideally be assessed?', '["Use exactly the same adult categories", "No need to measure until age 20", "Use growth charts/percentiles matched to age and sex", "Just guess from physical appearance"]'::jsonb, 2, 'Children are still growing, so their BMI is read through percentiles on growth charts — adult categories don''t apply as-is.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar' and locale = 'en'), 4, 'What should someone with a BMI of 27 conclude?', '["Definitely unhealthy and must start a strict diet immediately", "In the overweight category — use it as a trigger to review their lifestyle as a whole", "A BMI above 25 always means obesity", "No need to care since BMI is completely inaccurate"]'::jsonb, 1, 'A BMI of 27 means overweight, but it''s a starting point for evaluation (diet, activity, waist circumference), not a disease diagnosis.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at, locale) values ('kuis-kalori-energi', 'Calories & Energy', 'Trivia about calories, BMR, and TDEE.', (select id from public.knowledge_articles where slug = 'kalori-itu-energi' and locale = 'en'), 'published', now(), 'en') on conflict (slug, locale) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en'), 0, 'What actually is a calorie?', '["A harmful substance in fast food", "A unit of energy the body uses for activity", "A type of fat stored in the belly", "A hormone that makes you hungry quickly"]'::jsonb, 1, 'A calorie is simply a unit of energy — your body needs it to breathe, think, and exercise. The only issue is the amount.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en'), 1, 'What does BMR describe?', '["Calories burned during intense exercise", "The maximum calories you may eat per day", "Calories the body burns at total rest", "Metabolic speed after a big meal"]'::jsonb, 2, 'BMR is the energy for your body''s basic functions when you lie around all day doing nothing — usually estimated with the Mifflin-St Jeor formula.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en'), 2, 'Which statement about TDEE and BMR is correct?', '["TDEE is always smaller than BMR", "TDEE = BMR + daily activity energy", "TDEE and BMR are two names for the same thing", "TDEE only applies to athletes"]'::jsonb, 1, 'TDEE is the daily total: BMR plus all your activity. This is the number that sets your calorie needs.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en'), 3, 'A calorie deficit means…', '["Not eating at all for a whole day", "Taking in fewer calories than your body burns", "Avoiding all high-calorie foods forever", "Exercising until every calorie is burned off"]'::jsonb, 1, 'A gentle deficit of around 300–500 kcal per day is enough for healthy weight loss — no need to torment yourself.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi' and locale = 'en'), 4, 'Roughly how much energy is stored in 1 kg of body fat?', '["3,500 kcal", "5,000 kcal", "7,700 kcal", "10,000 kcal"]'::jsonb, 2, 'About 7,700 kcal per kg of fat — which is why a realistic target is gradual loss of around 0.5 kg per week, not instant.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at, locale) values ('kuis-mitos-fakta', 'Myths vs Facts: Healthy Habits', 'Tell popular myths apart from the facts.', null, 'published', now(), 'en') on conflict (slug, locale) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en'), 0, 'Myth or fact: ''Eating dinner will definitely make you gain weight.''', '["Fact — eating after 7 PM automatically turns into fat", "Myth — what matters is total daily calories, not meal timing", "Fact — metabolism stops completely during sleep", "Myth — eating dinner actually burns calories"]'::jsonb, 1, 'Your body has no magic clock that turns food into fat at exactly 7 PM. Total intake across the day is what matters.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en'), 1, 'Myth or fact: ''The more you sweat during exercise, the more fat you burn.''', '["Fact — sweat is melted fat", "Myth — sweat is mostly water; fat leaves through breath and metabolism", "Fact — applies to all types of exercise", "Myth — sweat has nothing to do with exercise at all"]'::jsonb, 1, 'Sweat is how your body cools down; it''s mostly water. Burned fat mostly leaves as carbon dioxide through your breath.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en'), 2, 'Myth or fact: ''Carbs must be avoided entirely to lose weight.''', '["Fact — carbs are the sole cause of weight gain", "Myth — carbs are the main energy source; what matters is the type and portion", "Fact — the body doesn''t need carbs at all", "Myth — carbs contain no calories"]'::jsonb, 1, 'Your brain and muscles need glucose from carbs. Choose fibrous ones and manage portions — no need to demonize one nutrient.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en'), 3, 'Myth or fact: ''Weighing yourself every day is mandatory to succeed.''', '["Fact — without a daily weigh-in, diets always fail", "Myth — what matters is a consistent schedule and reading the trend, not daily numbers", "Fact — daily weight never fluctuates", "Myth — weighing is completely forbidden"]'::jsonb, 1, 'Daily weight fluctuates with water and food. Weigh on the same schedule each week and watch the trend — that''s honest data.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta' and locale = 'en'), 4, 'Myth or fact: ''Lack of sleep can interfere with weight management.''', '["Myth — sleep has nothing to do with body weight", "Fact — lack of sleep disrupts hunger-fullness hormones and triggers snacking", "Myth — staying up late actually burns more calories", "Fact — lack of sleep directly adds 5 kg"]'::jsonb, 1, 'Poor sleep raises the hunger hormone (ghrelin) and lowers the fullness hormone (leptin). Getting enough sleep is a legitimate part of the strategy.');
